// Validate and enrich notification request
const body = $input.item.json.body || $input.item.json;
const severity = (body.severity || 'medium').toLowerCase();
const subject = body.subject || 'AISHA Notification';
const message = body.message || '';
const context = body.context || {};
const requiresResponse = body.requires_response || false;
const source = body.source || 'dirigent';
const timestamp = new Date().toISOString();

// Severity validation
const validSeverities = ['low', 'medium', 'high', 'critical'];
if (!validSeverities.includes(severity)) {
  return [{
    json: {
      error: true,
      message: `Invalid severity: ${severity}. Must be one of: ${validSeverities.join(', ')}`
    }
  }];
}

if (!message) {
  return [{
    json: {
      error: true,
      message: 'Missing required field: message'
    }
  }];
}

// Determine channels based on severity
const channels = {
  low: ['log'],
  medium: ['log', 'email_digest'],
  high: ['log', 'email_immediate'],
  critical: ['log', 'email_immediate', 'webhook_callback']
};

const notificationId = 'notif_' + Date.now() + '_' + Math.random().toString(36).substr(2, 6);

return [{
  json: {
    notificationId,
    severity,
    subject,
    message,
    context,
    requiresResponse,
    source,
    timestamp,
    channels: channels[severity],
    error: false
  }
}];

// LOW severity — log only, queue for daily digest
const input = $input.item.json;

return [{
  json: {
    delivered: true,
    notificationId: input.notificationId,
    channels: ['log'],
    message: `[LOW] ${input.subject}: ${input.message}`,
    digestQueued: true
  }
}];

// MEDIUM severity — store for email digest (sent at scheduled intervals)
const input = $input.item.json;

// Store in NocoDB notification_queue table for daily digest
return [{
  json: {
    delivered: true,
    notificationId: input.notificationId,
    channels: ['log', 'email_digest'],
    message: `[MEDIUM] ${input.subject}: ${input.message}`,
    digestQueued: true,
    digestData: {
      severity: input.severity,
      subject: input.subject,
      message: input.message,
      source: input.source,
      timestamp: input.timestamp,
      context: input.context
    }
  }
}];

// Merge all delivery results
const input = $input.item.json;
const severity = $('Validate & Enrich').item.json.severity;
const notificationId = $('Validate & Enrich').item.json.notificationId;

return [{
  json: {
    success: true,
    notificationId,
    severity,
    delivered: true,
    channels: $('Validate & Enrich').item.json.channels,
    timestamp: new Date().toISOString()
  }
}];
